test('Drive resuelve la jerarquía y recupera una subida con respuesta perdida sin duplicar fotos ni alterar cantidades',async t=>{
 const {guardarEvidencia}=await import('../../src/centro/evidencias.mjs'),{sincronizarEvidencia}=await import('../../src/centro/drive-evidencias.mjs'),{createHash}=await import('node:crypto'),f=await fixtureCentro(pool,t),p={actorId:f.actor},r=await crearDesdeCentro({pool:runtime,principal:p,solicitud:f.solicitud}),[[l]]=await pool.execute('SELECT id,conteo_1,version FROM ims_op_linea WHERE inventario_id=?',[r.inventarioId]),id=randomUUID(),base64='iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+j1ioAAAAASUVORK5CYII=';await guardarEvidencia(runtime,p,{operacionId:id,lineaId:l.id,base64,nota:'Prueba privada'});await pool.execute("INSERT INTO ims_cm_conector(tipo,cifrado,actor_id) VALUES ('GOOGLE_CALENDAR',?,?) ON DUPLICATE KEY UPDATE cifrado=VALUES(cifrado)",[cifrar({cuenta:'fotos@sintetico.invalid',driveArchivos:true,clienteId:'cliente-sintetico',clienteSecreto:'privado-sintetico',refreshToken:'token-sintetico'},'c'.repeat(64)),f.actor]);
 const objetos=new Map();let contador=0,incierta=true;const fetchMock=async(url,opts={})=>{const u=new URL(url);if(u.hostname==='oauth2.googleapis.com')return Response.json({access_token:'solo-prueba'});if(u.pathname.endsWith('/generateIds'))return Response.json({ids:['foto_id_'+(++contador)]});if(opts.method==='POST'){let m,bytes;if(u.pathname.startsWith('/upload/')){const bound=opts.headers['Content-Type'].split('boundary=')[1],parts=opts.body.toString('latin1').split('--'+bound);m=JSON.parse(parts[1].split('\r\n\r\n')[1].slice(0,-2));bytes=Buffer.from(parts[2].split('\r\n\r\n')[1].slice(0,-2),'latin1');}else m=JSON.parse(opts.body);objetos.set(m.id,{...m,...(bytes?{md5Checksum:createHash('md5').update(bytes).digest('hex')}:{})});if(bytes&&incierta){incierta=false;assert.deepEqual(bytes,Buffer.from(base64,'base64'));throw Error('Respuesta perdida sintética');}return Response.json({id:m.id});}const obj=objetos.get(u.pathname.split('/').at(-1));return obj?Response.json(obj):new Response('',{status:404});};
 await assert.rejects(()=>sincronizarEvidencia(runtime,p,id,'c'.repeat(64),fetchMock));assert.equal(objetos.size,6);const result=await sincronizarEvidencia(runtime,p,id,'c'.repeat(64),fetchMock);assert.equal(result.drive,'SUBIDO');assert.equal(objetos.size,6);assert.deepEqual([...objetos.values()].map(x=>x.name).slice(0,5),['ITSANET IMS','UIO','2026','11','BELIA']);const [[despues]]=await pool.execute('SELECT id,conteo_1,version FROM ims_op_linea WHERE id=?',[l.id]);assert.deepEqual(despues,l);
});

